      "desc": "鸳鸯榫是侗族鬭接榫卯的一种，是一种根据榫高二分的斜搭掌榫。",
      "enDesc": "The mandarin-duck joint is a type of mortise-and-tenon joint used by the Dong ethnic group.",
      "detail": "鸳鸯榫是侗族鬭接榫卯的一种，是一种根据榫高二分的斜搭掌榫。其搭掌长度比柱子卯口还要大，穿出卯口后会加柱外销锁固。两根构件在柱卯内斜搭接合，通过增加接触面积来增大摩擦力，是侗族木构建筑中常见的拼接榫卯之一。",
      "enDetail": "The mandarin-duck joint is a type of mortise-and-tenon joint used by the Dong ethnic group. It is an oblique overlay tenon based on half the tenon’s height. The length of the overlay exceeds the mortise of the column, and after passing through the mortise, it is secured with an external peg to lock it. The two components are obliquely joined within the column mortise, increasing friction through a larger contact area, making it one of the common mortise-and-tenon joints in Dong wooden architecture.",
