      "desc": "穿斗式每檩下皆有柱，柱间以穿枋透榫串联成纵向框架，省料而整体性强，南方民间与园林多用此种结构。",
      "enDesc": "In the dougong style, there is a column under each purlin, and the columns are connected by through beams with…",
      "detail": "穿斗式每檩下皆有柱，柱间以穿枋透榫串联成纵向框架，省料而整体性强，南方民间与园林多用此种结构。",
