          "cn": "再将螺丝榫上之螺丝钉旋去，按定其榫取出。",
          "tr": "螺丝榫配螺丝钉，旋下螺丝钉即可取出榫件",
          "en": "Then the screw on the screw tenon is unscrewed, and the tenon is pressed in place and taken out."
