          "cn": "造行营桥梁，如匠人凿眼斗榫之法，大约不用，而用绳索及曲铁之类，包扎稳固。",
          "tr": "建造行营桥梁时，像匠人凿眼斗榫的方法大多不用，而是用绳索、弯铁之类包扎稳固。"
