      "enDesc": "The inscription says: clean in conduct yet firm, refined in diction yet eloquent.",
      "detail": "",
      "enDetail": "The inscription says: clean in conduct yet firm, refined in diction yet eloquent. Though the handle and chisel are at odds, what harm in weighing righteousness? That essence and that weed measured by one gauge. Returning to serve by the south of the river, delighting in this vastness. Who is it that advances the worthy, resting with the sovereign's aid? The year hastens on; who inquires of yonder heaven? May his life be short no more, may his fame spread far. May the river roll on, may the letters flourish.",
